#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct TreeNode {
    int val;
    struct TreeNode *left, *right;
} TreeNode;

typedef struct {
    char **data;
    int size;
    int cap;
} StringVec;

static void push_string(StringVec *v, const char *s) {
    if (v->size == v->cap) {
        v->cap = v->cap ? v->cap * 2 : 8;
        v->data = realloc(v->data, v->cap * sizeof(char*));
    }
    char *copy = malloc(strlen(s) + 1); strcpy(copy, s); v->data[v->size++] = copy;
}

static void dfs(TreeNode *node, char **path, int depth, StringVec *out) {
    if (!node) return;
    char value[32];
    snprintf(value, sizeof(value), "%d", node->val);

    int len = 0;
    for (int i = 0; i < depth; ++i) len += (int)strlen(path[i]) + 2;
    len += (int)strlen(value) + 1;
    char *current = malloc((size_t)len);
    current[0] = '\0';

    for (int i = 0; i < depth; ++i) {
        if (i) strcat(current, "->");
        strcat(current, path[i]);
    }
    if (depth) strcat(current, "->");
    strcat(current, value);

    path[depth] = value;
    if (!node->left && !node->right) {
        push_string(out, current);
    } else {
        dfs(node->left, path, depth + 1, out);
        dfs(node->right, path, depth + 1, out);
    }
    free(current);
}

static TreeNode *build_tree(char **tokens, int n) {
    if (n == 0 || strcmp(tokens[0], "null") == 0) return NULL;
    TreeNode **queue = malloc((size_t)n * sizeof(TreeNode*));
    TreeNode *root = malloc(sizeof(TreeNode));
    root->val = atoi(tokens[0]); root->left = root->right = NULL;
    queue[0] = root;
    int head = 0, tail = 1, i = 1;

    while (head < tail && i < n) {
        TreeNode *node = queue[head++];
        if (i < n && strcmp(tokens[i], "null") != 0) {
            node->left = malloc(sizeof(TreeNode));
            node->left->val = atoi(tokens[i]);
            node->left->left = node->left->right = NULL;
            queue[tail++] = node->left;
        }
        ++i;
        if (i < n && strcmp(tokens[i], "null") != 0) {
            node->right = malloc(sizeof(TreeNode));
            node->right->val = atoi(tokens[i]);
            node->right->left = node->right->right = NULL;
            queue[tail++] = node->right;
        }
        ++i;
    }
    free(queue);
    return root;
}

int main(void) {
    char line[1000000];
    if (!fgets(line, sizeof(line), stdin)) return 0;

    char *start = strstr(line, "[[");
    if (!start) return 1;
    start += 2;
    char *end = strstr(start, "]]");
    if (!end) return 1;
    *end = '\0';

    char *tokens[128];
    int n = 0;
    char *tok = strtok(start, ",");
    while (tok && n < 128) {
        while (*tok == ' ' || *tok == '\t') ++tok;
        char *p = tok + strlen(tok) - 1;
        while (p >= tok && (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r')) *p-- = '\0';
        tokens[n++] = tok;
        tok = strtok(NULL, ",");
    }

    TreeNode *root = build_tree(tokens, n);
    char *path[128];
    StringVec out = {0};
    dfs(root, path, 0, &out);

    printf("[");
    for (int i = 0; i < out.size; ++i) {
        if (i) printf(",");
        printf("\"%s\"", out.data[i]);
        free(out.data[i]);
    }
    printf("]\n");
    free(out.data);
    return 0;
}

