import java.io.*;
import java.util.*;

class TreeNode {
    int val;
    TreeNode left, right;
    TreeNode(int val) { this.val = val; }
}

class Solution {
    public List<String> binaryTreePaths(TreeNode root) {
        List<String> result = new ArrayList<>();
        List<String> path = new ArrayList<>();
        dfs(root, path, result);
        return result;
    }

    private void dfs(TreeNode node, List<String> path, List<String> result) {
        if (node == null) return;
        path.add(String.valueOf(node.val));
        if (node.left == null && node.right == null) {
            result.add(String.join("->", path));
        } else {
            dfs(node.left, path, result);
            dfs(node.right, path, result);
        }
        path.remove(path.size() - 1);
    }
}

public class Main {
    static TreeNode buildTree(String[] values) {
        if (values.length == 0) return null;
        TreeNode root = new TreeNode(Integer.parseInt(values[0].trim()));
        ArrayDeque<TreeNode> q = new ArrayDeque<>();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < values.length) {
            TreeNode node = q.remove();
            if (i < values.length && !values[i].trim().equals("null")) {
                node.left = new TreeNode(Integer.parseInt(values[i].trim()));
                q.add(node.left);
            }
            i++;
            if (i < values.length && !values[i].trim().equals("null")) {
                node.right = new TreeNode(Integer.parseInt(values[i].trim()));
                q.add(node.right);
            }
            i++;
        }
        return root;
    }

    static String[] parseValues(String line) {
        String s = line.trim();
        int start = s.indexOf("[[") + 2;
        int end = s.lastIndexOf("]]");
        String body = s.substring(start, end);
        if (body.trim().isEmpty()) return new String[0];
        return body.split(",");
    }

    static String toJson(List<String> result) {
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < result.size(); i++) {
            if (i > 0) sb.append(',');
            sb.append('"').append(result.get(i)).append('"');
        }
        return sb.append(']').toString();
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        TreeNode root = buildTree(parseValues(line));
        System.out.println(toJson(new Solution().binaryTreePaths(root)));
    }
}

